INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('be96c895-5c75-5079-8ac3-1da85a1011ee', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 1, 1, 'A light gate is connected to a timer. What does it measure directly?', NULL, 1, 'multiple_choice'::answer_type, 'The time for which an object blocks its beam', NULL, false, NULL, false, NULL, 'Speed is then found from the length of the card ÷ the time. Mark scheme (1 mark). B1: C (The time for which an object blocks its beam).', 1, NULL, NULL),
('c19371b0-337b-5931-b71e-0510ba1f91fa', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 2, 2, 'A 5.0 cm card on a trolley blocks a light gate for 0.10 s. Calculate the speed of the trolley.', NULL, 1, 'numeric'::answer_type, '0.5', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.050 ÷ 0.10 = 0.50 m s⁻¹. Mark scheme (2 marks). C1: length ÷ time. A1: v = 0.50 m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg9d72b1e2-t fg9d72b1e2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9d72b1e2-t">Card and light gate</title><desc id="fg9d72b1e2-d">A trolley carrying a 5.0 cm card passing through one light gate.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="270" y1="140" x2="262" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="140" x2="302" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350" y1="140" x2="342" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="390" y1="140" x2="382" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="40" y="112" width="70" height="22" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="54" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="96" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="68" y="82" width="14" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="75" y="70" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 cm card</text><line x1="118" y1="123" x2="144.4" y2="123" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,123 142.7,126.4 142.7,119.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><path d="M236,136 L236,66 L268,66 L268,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="238" y1="95" x2="266" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="252" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">light gate</text></svg>', 'A trolley carrying a 5.0 cm card passing through one light gate.'),
('375715dc-449f-5e5d-a159-87c7b584e934', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 3, 3, 'Why is a light gate better than a stopwatch for timing a fast trolley?', NULL, 1, 'multiple_choice'::answer_type, 'It removes human reaction time and times to the millisecond', NULL, false, NULL, false, NULL, 'Electronic timing is far more precise for short times. Mark scheme (1 mark). B1: A (It removes human reaction time and times to the millisecond).', 1, NULL, NULL),
('cc5fcaba-31f8-5966-a790-820e9a4975ce', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 4, 4, 'A ticker-timer makes 50 dots per second. What time interval separates two adjacent dots?', NULL, 1, 'numeric'::answer_type, '0.02', 's', false, NULL, false, NULL, 't = 1 ÷ 50 = 0.020 s. Mark scheme (2 marks). C1: 1/f. A1: t = 0.020 s.', 2, NULL, NULL),
('a3227fd2-0bf2-5ae0-8e25-cfe2b8b28a78', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 5, 5, 'On a ticker tape from a trolley, the dots get further apart along the tape. What does this show?', NULL, 1, 'multiple_choice'::answer_type, 'The trolley was accelerating', NULL, false, NULL, false, NULL, 'Equal times with increasing distances mean increasing speed. Mark scheme (1 mark). B1: D (The trolley was accelerating).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 120" role="img" aria-labelledby="fgb678fbff-t fgb678fbff-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb678fbff-t">Ticker tape</title><desc id="fgb678fbff-d">A ticker tape whose dot spacing increases steadily along its length.</desc><rect x="24" y="30" width="392" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="34" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="47.8" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="68.4" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="96" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="130.4" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="171.8" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="220" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="275.1" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="337.1" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="406" cy="46" r="3" style="fill:currentColor;stroke:none"/></svg>', 'A ticker tape whose dot spacing increases steadily along its length.'),
('61f26ea5-e61a-5472-9d35-02a4eba1d410', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 6, 6, 'Five dot-spaces on a 50 Hz ticker tape measure 4.0 cm. Calculate the average speed over these spaces.', NULL, 1, 'numeric'::answer_type, '0.4', 'm s⁻¹', false, NULL, false, NULL, 't = 5 × 0.020 = 0.10 s; v = 0.040 ÷ 0.10 = 0.40 m s⁻¹. Mark scheme (2 marks). C1: time for 5 spaces. A1: v = 0.40 m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 120" role="img" aria-labelledby="fgde4a4350-t fgde4a4350-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgde4a4350-t">Ticker tape</title><desc id="fgde4a4350-d">A ticker tape with six dots; the five spaces between them measure 4.0 cm.</desc><rect x="24" y="30" width="332" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="34" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="96.4" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="158.8" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="221.2" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="283.6" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="346" cy="46" r="3" style="fill:currentColor;stroke:none"/><polygon points="34,80 40.3,77 40.3,83" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="38.9" y1="80" x2="341.1" y2="80" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="346,80 339.7,83 339.7,77" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="190" y="92" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 cm</text><line x1="34" y1="64" x2="34" y2="84" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="346" y1="64" x2="346" y2="84" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'A ticker tape with six dots; the five spaces between them measure 4.0 cm.'),
('25cff1ce-0f2b-56e6-8ef4-02468d5ac104', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 7, 7, 'How does an ultrasonic motion sensor find the distance to a trolley?', NULL, 1, 'multiple_choice'::answer_type, 'It times how long an ultrasound pulse takes to reflect back', NULL, false, NULL, false, NULL, 'distance = speed of sound × time ÷ 2. Mark scheme (1 mark). B1: B (It times how long an ultrasound pulse takes to reflect back).', 1, NULL, NULL),
('9e86148b-f6f9-532c-bd72-5ce76114ed85', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 8, 8, 'A video camera records 25 frames per second. What time passes between successive frames?', NULL, 1, 'numeric'::answer_type, '0.04', 's', false, NULL, false, NULL, 't = 1 ÷ 25 = 0.040 s. Mark scheme (2 marks). C1: 1/frame rate. A1: t = 0.040 s.', 2, NULL, NULL),
('a75c0a1d-f9e7-5190-8afa-ff34dd0180cb', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 9, 9, 'Between two video frames 0.040 s apart, a ball moves 18 cm. Calculate its average speed.', NULL, 1, 'numeric'::answer_type, '4.5', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.18 ÷ 0.040 = 4.5 m s⁻¹. Mark scheme (2 marks). C1: cm to m. A1: v = 4.5 m s⁻¹.', 2, NULL, NULL),
('f8476b8c-578f-5bb3-9cb1-e90498d00790', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 10, 10, 'Which quantity must be measured, together with the speeds at two light gates, to find the acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'The time taken to travel between the gates', NULL, false, NULL, false, NULL, 'a = (v − u)/t, so the time between the gates is needed. Mark scheme (1 mark). B1: C (The time taken to travel between the gates).', 1, NULL, NULL),
('2d0a5423-ea43-5b64-be40-2dd06c380f52', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 11, 11, 'A trolley passes gate A at 0.30 m s⁻¹ and gate B at 0.70 m s⁻¹, 0.50 s later. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '0.8', 'm s⁻²', false, NULL, false, NULL, 'a = (0.70 − 0.30) ÷ 0.50 = 0.80 m s⁻². Mark scheme (2 marks). C1: Δv/t. A1: a = 0.80 m s⁻².', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg07efd5c5-t fg07efd5c5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg07efd5c5-t">Two light gates</title><desc id="fg07efd5c5-d">A trolley with a card passing light gates A and B.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="270" y1="140" x2="262" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="140" x2="302" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350" y1="140" x2="342" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="390" y1="140" x2="382" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="40" y="112" width="70" height="22" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="54" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="96" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="68" y="82" width="14" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="75" y="70" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">card</text><line x1="118" y1="123" x2="144.4" y2="123" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,123 142.7,126.4 142.7,119.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><path d="M185.6,136 L185.6,66 L217.6,66 L217.6,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="187.6" y1="95" x2="215.6" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="201.6" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gate A</text><path d="M328.4,136 L328.4,66 L360.4,66 L360.4,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="330.4" y1="95" x2="358.4" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="344.4" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gate B</text></svg>', 'A trolley with a card passing light gates A and B.'),
('c67f6e90-94be-530f-94b0-e6285753c451', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 12, 12, 'In a stroboscopic photograph, a falling ball appears at equal time intervals. How does the photo show that the ball accelerates?', NULL, 1, 'multiple_choice'::answer_type, 'The gaps between successive images increase', NULL, false, NULL, false, NULL, 'Larger distances in equal times mean larger speeds. Mark scheme (1 mark). B1: A (The gaps between successive images increase).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 330" role="img" aria-labelledby="fg5348a8bb-t fg5348a8bb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5348a8bb-t">Multiflash photograph</title><desc id="fg5348a8bb-d">Images of a falling ball at equal time intervals beside a vertical scale; the gaps between images grow.</desc><line x1="104" y1="30" x2="104" y2="300" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="98" y1="30" x2="104" y2="30" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="30" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="98" y1="68.6" x2="104" y2="68.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="68.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><line x1="98" y1="107.1" x2="104" y2="107.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="107.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">40</text><line x1="98" y1="145.7" x2="104" y2="145.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="145.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">60</text><line x1="98" y1="184.3" x2="104" y2="184.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="184.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">80</text><line x1="98" y1="222.9" x2="104" y2="222.9" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="222.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">100</text><line x1="98" y1="261.4" x2="104" y2="261.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="261.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">120</text><line x1="98" y1="300" x2="104" y2="300" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="92" y="300" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">140</text><text x="104" y="16" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">cm</text><circle cx="150" cy="30" r="7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="30" x2="141" y2="30" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><circle cx="150" cy="39.5" r="7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="39.5" x2="141" y2="39.5" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><circle cx="150" cy="67.8" r="7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="67.8" x2="141" y2="67.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><circle cx="150" cy="115.1" r="7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="115.1" x2="141" y2="115.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><circle cx="150" cy="181.4" r="7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="181.4" x2="141" y2="181.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><circle cx="150" cy="266.5" r="7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="266.5" x2="141" y2="266.5" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'Images of a falling ball at equal time intervals beside a vertical scale; the gaps between images grow.'),
('8b2ebfe4-965c-552d-8463-7e93e651b8a5', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 13, 13, 'A stroboscope flashes 20 times per second. What is the time between flashes?', NULL, 1, 'numeric'::answer_type, '0.05', 's', false, NULL, false, NULL, 't = 1 ÷ 20 = 0.050 s. Mark scheme (1 mark). A1: t = 0.050 s.', 1, NULL, NULL),
('e43e6713-dadf-57e0-bbc5-ee83ab183bb4', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 14, 14, 'What is an advantage of using a data logger with a motion sensor?', NULL, 1, 'multiple_choice'::answer_type, 'It records many readings very quickly and can plot graphs directly', NULL, false, NULL, false, NULL, 'Useful for rapidly changing motion. Mark scheme (1 mark). B1: D (It records many readings very quickly and can plot graphs directly).', 1, NULL, NULL),
('0cd0d157-e03e-519b-8f2a-a185102939e0', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 15, 15, 'An ultrasound pulse from a motion sensor returns after 0.012 s. Sound travels at 340 m s⁻¹. How far away is the trolley?', NULL, 1, 'numeric'::answer_type, '2.04', 'm', false, NULL, false, NULL, 'd = 340 × 0.012 ÷ 2 = 2.04 m. Mark scheme (2 marks). C1: halve the echo time. A1: d = 2.04 m.', 2, NULL, NULL),
('72561d27-66c8-5dff-bee7-ecdee4f8c66e', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 16, 16, 'Why should the card on a trolley be narrow when finding its speed at one point with a light gate?', NULL, 1, 'multiple_choice'::answer_type, 'The speed changes little while the card passes, so it is close to the instantaneous speed', NULL, false, NULL, false, NULL, 'The measured value is an average over the card length. Mark scheme (1 mark). B1: B (The speed changes little while the card passes, so it is close to the instantaneous speed).', 1, NULL, NULL),
('0a61e1ae-c0d4-5696-929e-2bdeca328f7e', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 17, 17, 'A ball in a multiflash photograph moves 12 cm between flashes 0.050 s apart. Calculate its speed.', NULL, 1, 'numeric'::answer_type, '2.4', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.12 ÷ 0.050 = 2.4 m s⁻¹. Mark scheme (2 marks). C1: d/t. A1: v = 2.4 m s⁻¹.', 2, NULL, NULL),
('0f769bdb-d3be-5f35-8496-dd0166e41f9a', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 18, 18, 'A 10 cm card on a falling object cuts a light beam for 0.025 s. Calculate its speed.', NULL, 1, 'numeric'::answer_type, '4', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.10 ÷ 0.025 = 4.0 m s⁻¹. Mark scheme (2 marks). C1: length ÷ time. A1: v = 4.0 m s⁻¹.', 2, NULL, NULL),
