('c327003d-7f3f-5393-af65-60f207858f8c', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 20, 20, 'A ball rolls between two marks 0.36 m apart in 0.90 s. Calculate its average speed.', NULL, 1, 'numeric'::answer_type, '0.4', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.36 ÷ 0.90 = 0.40 m s⁻¹. Mark scheme (2 marks). C1: d/t. A1: v = 0.40 m s⁻¹.', 2, NULL, NULL),
('9cfcce08-a5ff-5ebb-9086-df2b3206bcbb', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 21, 21, 'Which instrument is best for measuring the length of the card on a trolley, about 5 cm?', NULL, 1, 'multiple_choice'::answer_type, 'Vernier calipers', NULL, false, NULL, false, NULL, 'Calipers read to 0.01 cm, reducing the percentage uncertainty. Mark scheme (1 mark). B1: D (Vernier calipers).', 1, NULL, NULL),
('78c3cdd8-8ed6-52cf-9b86-6a34ad1e2bcf', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'a-level', '2.6', '9702 coursebook 2.6 · Measuring velocity and acceleration', 22, 22, 'A 4.0 cm card blocks gate A for 0.080 s and gate B for 0.040 s; the trolley takes 0.60 s from A to B. Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '0.8333', 'm s⁻²', false, NULL, false, NULL, 'u = 0.040 ÷ 0.080 = 0.50 m s⁻¹; v = 0.040 ÷ 0.040 = 1.0 m s⁻¹; a = (1.0 − 0.50) ÷ 0.60 = 0.833 m s⁻². Mark scheme (3 marks). C1: both speeds. C1: a = Δv/t. A1: a = 0.833 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg677ec462-t fg677ec462-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg677ec462-t">Two light gates</title><desc id="fg677ec462-d">A trolley carrying a 4.0 cm card passing light gates A and B.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="270" y1="140" x2