stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="29" y1="172.7" x2="33" y2="172.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="172.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.6</text><line x1="29" y1="103.3" x2="33" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.8</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">s / m</text><line x1="29" y1="203.3" x2="37" y2="211.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29" y1="211.3" x2="37" y2="203.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145.4" y1="175.6" x2="153.4" y2="183.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145.4" y1="183.6" x2="153.4" y2="175.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="261.7" y1="127.1" x2="269.7" y2="135.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="261.7" y1="135.1" x2="269.7" y2="127.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="378" y1="57.7" x2="386" y2="65.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="378" y1="65.7" x2="386" y2="57.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="27" y1="232" x2="39" y2="226" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="27" y1="226" x2="39" y2="220" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Displacement against time from a motion sensor: 0.50, 0.58, 0.72 and 0.92 m at 0.10 s intervals.')
