INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('cba48396-b065-5e46-b0d2-1ec1b7636c88', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 1, 1, 'A trolley is released on a ramp and passes one light gate. What extra information is needed to find its speed?', NULL, 1, 'multiple_choice'::answer_type, 'The length of the card that blocks the beam', NULL, false, NULL, false, NULL, 'speed = card length ÷ block time. Mark scheme (1 mark). B1: C (The length of the card that blocks the beam).', 1, NULL, NULL),
('ca6f6526-0003-585a-8aa2-27a8f9eb9187', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 2, 2, 'Why is the ramp sometimes tilted slightly so that a pushed trolley runs at constant speed?', NULL, 1, 'multiple_choice'::answer_type, 'To compensate for friction', NULL, false, NULL, false, NULL, 'Then any acceleration is due only to the applied force. Mark scheme (1 mark). B1: A (To compensate for friction).', 1, NULL, NULL),
('4301dd75-3f3f-55dd-b278-47d696b544a9', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 3, 3, 'A trolley''s 6.0 cm card blocks a light gate for 0.15 s. Calculate its speed.', NULL, 1, 'numeric'::answer_type, '0.4', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.060 ÷ 0.15 = 0.40 m s⁻¹. Mark scheme (2 marks). C1: length ÷ time. A1: v = 0.40 m s⁻¹.', 2, NULL, NULL),
('464de787-ed26-59d2-9b9b-99baed4cee1e', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 4, 4, 'Which arrangement can measure the acceleration of a trolley?', NULL, 1, 'multiple_choice'::answer_type, 'Two light gates a measured distance apart, or one gate with a double-interrupt card', NULL, false, NULL, false, NULL, 'Two speeds are needed. Mark scheme (1 mark). B1: D (Two light gates a measured distance apart, or one gate with a double-interrupt card).', 1, NULL, NULL),
('6ca07d6d-ce07-5f0e-b558-f99cfb644759', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 5, 5, 'A trolley''s speed at gate 1 is 0.60 m s⁻¹ and at gate 2 is 1.20 m s⁻¹; the timer records 0.40 s between them. Calculate the acceleration.', NULL, 1, 'numeric'::answer_type, '1.5', 'm s⁻²', false, NULL, false, NULL, 'a = (1.20 − 0.60) ÷ 0.40 = 1.5 m s⁻². Mark scheme (2 marks). C1: Δv/t. A1: a = 1.5 m s⁻².', 2, NULL, NULL),
('f9c955bb-2d66-598e-8ebf-df4f1a39d1cc', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 6, 6, 'Why are measurements repeated when finding the acceleration of a trolley?', NULL, 1, 'multiple_choice'::answer_type, 'To reduce random error and spot anomalous results', NULL, false, NULL, false, NULL, 'A mean of repeats is more reliable. Mark scheme (1 mark). B1: B (To reduce random error and spot anomalous results).', 1, NULL, NULL),
('2b1cae78-467f-5d36-95d3-d0bf9fa70f6a', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 7, 7, 'Repeat block times at a light gate are 0.121 s, 0.118 s and 0.124 s. Calculate the mean.', NULL, 1, 'numeric'::answer_type, '0.121', 's', false, NULL, false, NULL, 'Mean = (0.121 + 0.118 + 0.124) ÷ 3 = 0.121 s. Mark scheme (2 marks). C1: mean. A1: t = 0.121 s.', 2, NULL, NULL),
('fe91c2d5-5f5c-5bd8-9978-a48a25e2c58d', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 8, 8, 'What is the advantage of plotting a v–t graph from several measurements rather than using two speeds?', NULL, 1, 'multiple_choice'::answer_type, 'The gradient of the best-fit line averages out random errors', NULL, false, NULL, false, NULL, 'More points give a more reliable acceleration. Mark scheme (1 mark). B1: C (The gradient of the best-fit line averages out random errors).', 1, NULL, NULL),
('c73c6edc-1afe-50f0-978d-70d8deb51dca', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 9, 9, 'A trolley starts from rest and reaches 0.90 m s⁻¹ at a light gate 1.5 s after release. Calculate its average acceleration.', NULL, 1, 'numeric'::answer_type, '0.6', 'm s⁻²', false, NULL, false, NULL, 'a = 0.90 ÷ 1.5 = 0.60 m s⁻². Mark scheme (2 marks). C1: a = v/t. A1: a = 0.60 m s⁻².', 2, NULL, NULL),
('2be18405-b1e8-5597-a53a-406118490e0b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 10, 10, 'A student measures the distance between two light gates with a metre rule. Which instrument resolution is typical?', NULL, 1, 'multiple_choice'::answer_type, '1 mm', NULL, false, NULL, false, NULL, 'Metre rules are marked in millimetres. Mark scheme (1 mark). B1: A (1 mm).', 1, NULL, NULL),
('70ad26fe-1c1f-5cd6-a74b-5997d79fc70f', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 11, 11, 'A trolley released from rest travels 0.80 m in 1.6 s with uniform acceleration. Calculate its acceleration using s = ½at².', NULL, 1, 'numeric'::answer_type, '0.625', 'm s⁻²', false, NULL, false, NULL, 'a = 2 × 0.80 ÷ 1.6² = 0.625 m s⁻². Mark scheme (2 marks). C1: a = 2s/t². A1: a = 0.625 m s⁻².', 2, NULL, NULL),
('f252065a-20c1-5942-b934-7d51e1530520', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 12, 12, 'Why should the trolley be released rather than pushed when measuring acceleration down a ramp?', NULL, 1, 'multiple_choice'::answer_type, 'So that its initial velocity is zero and known', NULL, false, NULL, false, NULL, 'A push gives an unknown starting speed. Mark scheme (1 mark). B1: D (So that its initial velocity is zero and known).', 1, NULL, NULL),
('7f59d728-9e0b-5ff6-a4ab-d98082edfd4c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 13, 13, 'A ball rolls 1.2 m from rest down a ramp in 2.0 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '0.6', 'm s⁻²', false, NULL, false, NULL, 'a = 2s ÷ t² = 2 × 1.2 ÷ 2.0² = 0.60 m s⁻². Mark scheme (2 marks). C1: s = ½at². A1: a = 0.60 m s⁻².', 2, NULL, NULL),
('33a68864-7159-5cf7-95c9-2d85fe88e3cb', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 14, 14, 'Which graph should give a straight line for a trolley accelerating uniformly from rest?', NULL, 1, 'multiple_choice'::answer_type, 'v against t', NULL, false, NULL, false, NULL, 'v = at is linear in t. Mark scheme (1 mark). B1: B (v against t).', 1, NULL, NULL),
('4e29b641-09fa-5ac0-bf79-10911bb8da55', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 15, 15, 'A trolley at 0.25 m s⁻¹ accelerates at 0.50 m s⁻² for 2.0 s. Calculate its final speed.', NULL, 1, 'numeric'::answer_type, '1.25', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.25 + 0.50 × 2.0 = 1.25 m s⁻¹. Mark scheme (1 mark). A1: v = 1.25 m s⁻¹.', 1, NULL, NULL),
('5c333743-16ac-5493-bd1a-873b5bb564a4', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 16, 16, 'What is the effect of friction on the measured acceleration of a trolley rolling down a ramp?', NULL, 1, 'multiple_choice'::answer_type, 'It makes the measured acceleration smaller than the frictionless value', NULL, false, NULL, false, NULL, 'Friction opposes the motion. Mark scheme (1 mark). B1: C (It makes the measured acceleration smaller than the frictionless value).', 1, NULL, NULL),
('5313979d-6c3e-5fa1-a5a4-fcb3ef265ba8', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 17, 17, 'A light gate records 0.050 s for a 2.5 cm card. Calculate the trolley speed.', NULL, 1, 'numeric'::answer_type, '0.5', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.025 ÷ 0.050 = 0.50 m s⁻¹. Mark scheme (2 marks). C1: length ÷ time. A1: v = 0.50 m s⁻¹.', 2, NULL, NULL),
('e963098c-557e-5213-bad5-4d86ea482d95', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 18, 18, 'The two light gates are measured to be 50.0 cm apart with an uncertainty of ±0.1 cm. Calculate the percentage uncertainty.', NULL, 1, 'numeric'::answer_type, '0.2', '%', false, NULL, false, NULL, '% = 0.1 ÷ 50.0 × 100 = 0.2 %. Mark scheme (2 marks). C1: Δx/x × 100. A1: % uncertainty = 0.2%.', 2, NULL, NULL),
('a124da1d-f0d0-52df-b803-53b85dfeff3c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 19, 19, 'To investigate how a trolley''s acceleration depends on the slope, which variable is changed?', NULL, 1, 'multiple_choice'::answer_type, 'The angle of the ramp', NULL, false, NULL, false, NULL, 'The angle is the independent variable. Mark scheme (1 mark). B1: B (The angle of the ramp).', 1, NULL, NULL),
('4ec0264b-abc6-5e2b-9fb2-74f05dcf35e1', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 20, 20, 'A trolley passes the first gate at 0.35 m s⁻¹ and accelerates at 0.50 m s⁻² for 0.80 s to the second gate. Calculate its speed at the second gate.', NULL, 1, 'numeric'::answer_type, '0.75', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.35 + 0.50 × 0.80 = 0.75 m s⁻¹. Mark scheme (2 marks). C1: v = u + at. A1: v = 0.75 m s⁻¹.', 2, NULL, NULL),
('5d158988-1037-57e7-9f39-dca7b9584e57', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 21, 21, 'A trolley released from rest passes light gates 0.30 m and 0.90 m down a ramp at 0.60 m s⁻¹ and 1.04 m s⁻¹. Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '0.6013', 'm s⁻²', false, NULL, false, NULL, 'a = (1.04² − 0.60²) ÷ (2 × 0.60) = 0.601 m s⁻². Mark scheme (3 marks). C1: v² = u² + 2as. C1: s = 0.60 m. A1: a = 0.601 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg78ddcb0d-t fg78ddcb0d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg78ddcb0d-t">Gates 0.60 m apart</title><desc id="fg78ddcb0d-d">A trolley passing two light gates on a ramp, 0.30 m and 0.90 m from its release point (0.60 m apart).</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="270" y1="140" x2="262" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="140" x2="302" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350" y1="140" x2="342" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="390" y1="140" x2="382" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="40" y="112" width="70" height="22" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="54" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="96" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="68" y="82" width="14" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="75" y="70" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">card</text><line x1="118" y1="123" x2="144.4" y2="123" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,123 142.7,126.4 142.7,119.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><path d="M185.6,136 L185.6,66 L217.6,66 L217.6,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="187.6" y1="95" x2="215.6" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="201.6" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gate A</text><path d="M328.4,136 L328.4,66 L360.4,66 L360.4,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="330.4" y1="95" x2="358.4" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="344.4" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gate B</text><polygon points="201.6,162 207.9,159 207.9,165" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="206.5" y1="162" x2="339.5" y2="162" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="344.4,162 338.1,165 338.1,159" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="273" y="174" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.60 m</text></svg>', 'A trolley passing two light gates on a ramp, 0.30 m and 0.90 m from its release point (0.60 m apart).'),
('077b39ce-8275-5ce0-b388-8c76fc112381', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 22, 22, 'A student plots s against t² for a trolley released from rest. What should the graph look like, and what is its gradient?', NULL, 2, 'multiple_choice'::answer_type, 'A straight line through the origin with gradient a/2', NULL, false, NULL, false, NULL, 's = ½at², so s ∝ t² with gradient a/2. Mark scheme (3 marks). C1: straight line through origin. C1: gradient a/2. A1: A (A straight line through the origin with gradient a/2).', 3, NULL, NULL),
('a625a709-5489-5195-bd61-2355caac3931', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 23, 23, 'A graph of s against t² for a trolley released from rest has gradient 0.36 m s⁻². Calculate the acceleration.', NULL, 2, 'numeric'::answer_type, '0.72', 'm s⁻²', false, NULL, false, NULL, 'Gradient = a/2, so a = 2 × 0.36 = 0.72 m s⁻². Mark scheme (3 marks). C1: gradient = a/2. C1: value. A1: a = 0.72 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgf55384e7-t fgf55384e7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf55384e7-t">s against t²</title><desc id="fgf55384e7-d">A straight line through the origin on a graph of s against t², gradient 0.36 m s⁻².</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120.3" y1="34" x2="120.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207.5" y1="34" x2="207.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="294.8" y1="34" x2="294.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;strok