('1b3d8a40-1da7-5031-ab4a-5ac3c6664293', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 24, 24, 'A graph of v² against s for a trolley has gradient 1.6 m s⁻². Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '0.8', 'm s⁻²', false, NULL, false, NULL, 'v² = u² + 2as, so gradient = 2a and a = 1.6 ÷ 2 = 0.80 m s⁻². Mark scheme (3 marks). C1: gradient = 2a. C1: value. A1: a = 0.80 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgc2c438a8-t fgc2c438a8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc2c438a8-t">v² against s</title><desc id="fgc2c438a8-d">A straight line through the origin on a graph of v² against s, gradient 1.6 m s⁻².</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="102.8" y1="34" x2="102.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172.6" y1="34" x2="172.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="242.4" y1="34" x2="242.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.2" y1="34" x2="312.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-l