currentColor">0.6</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="200.4" x2="33" y2="200.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="200.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.1</text><line x1="29" y1="158.8" x2="33" y2="158.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="158.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.2</text><line x1="29" y1="117.2" x2="33" y2="117.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="117.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.3</text><line x1="29" y1="75.6" x2="33" y2="75.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="75.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">v / m s⁻¹</text><polyline points="33,200.4 382,50.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29" y1="196.4" x2="37" y2="204.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29" y1="204.4" x2="37" y2="196.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145.4" y1="146.5" x2="153.4" y2="154.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145.4" y1="154.5" x2="153.4" y2="146.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="261.7" y1="96.6" x2="269.7" y2="104.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="261.7" y1="104.6" x2="269.7" y2="96.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="378" y1="46.6" x2="386" y2="54.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="378" y1="54.6" x2="386" y2="46.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Velocity readings 0.10, 0.22, 0.34 and 0.46 m s⁻¹ at 0.2 s intervals, on a straight line.'),
('9a84a60b-5dc4-55ec-9d32-cd471ccd6ac6', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 34, 34, 'A student wants to show that acceleration down a ramp depends on its angle. Which variable must be kept constant?', NULL, 2, 'multiple_choice'::answer_type, 'The trolley and the surface of the ramp (to keep friction the same)', NULL, false, NULL, false, NULL, 'Only the angle should change. Mark scheme (3 marks). C1: control variable. C1: reason. A1: A (The trolley and the surface of the ramp (to keep friction the same)).', 3, NULL, NULL),
('1c47757a-4b00-5db0-9950-db7169e2befc', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 35, 35, 'A trolley starting from rest takes 2.5 s to travel 1.5 m down a ramp. Calculate its speed at the end.', NULL, 2, 'numeric'::answer_type, '1.2', 'm s⁻¹', false, NULL, false, NULL, 'Average speed = 1.5 ÷ 2.5 = 0.60 m s⁻¹ = v/2, so v = 2 × 0.60 = 1.2 m s⁻¹. Mark scheme (3 marks). C1: average speed. C1: v = 2 × average. A1: v = 1.2 m s⁻¹.', 3, NULL, NULL),
('663c421c-a329-5223-b92c-a9373cd7943e', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 36, 36, 'A glider on an air track is pulled by a falling mass. Light gates 0.50 m apart record speeds of 0.40 m s⁻¹ and 0.90 m s⁻¹. Calculate the glider''s acceleration.', NULL, 2, 'numeric'::answer_type, '0.65', 'm s⁻²', false, NULL, false, NULL, 'a = (0.90² − 0.40²) ÷ (2 × 0.50) = 0.65 m s⁻². Mark scheme (3 marks). C1: v² = u² + 2as. C1: value. A1: a = 0.65 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg6bc2c6ab-t fg6bc2c6ab-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6bc2c6ab-t">Air-track glider</title><desc id="fg6bc2c6ab-d">A glider carrying a card passing two light gates 0.50 m apart.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="270" y1="140" x2="262" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="140" x2="302" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350" y1="140" x2="342" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="390" y1="140" x2="382" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="40" y="112" width="70" height="22" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="54" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="96" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="68" y="82" width="14" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="75" y="70" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">card</text><line x1="118" y1="123" x2="144.4" y2="123" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,123 142.7,126.4 142.7,119.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><path d="M185.6,136 L185.6,66 L217.6,66 L217.6,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="187.6" y1="95" x2="215.6" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="201.6" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gate A</text><path d="M328.4,136 L328.4,66 L360.4,66 L360.4,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="330.4" y1="95" x2="358.4" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="344.4" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">gate B</text><polygon points="201.6,162 207.9,159 207.9,165" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="206.5" y1="162" x2="339.5" y2="162" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="344.4,162 338.1,165 338.1,159" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="273" y="174" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.50 m</text></svg>', 'A glider carrying a card passing two light gates 0.50 m apart.'),
('463053e6-ed2f-57cb-8735-45f86c022443', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 37, 37, 'Why is an air track used for some acceleration experiments?', NULL, 2, 'multiple_choice'::answer_type, 'It almost removes friction, so the measured acceleration matches theory more closely', NULL, false, NULL, false, NULL, 'The glider floats on a cushion of air. Mark scheme (3 marks). C1: reduces friction. C1: closer to theory. A1: D (It almost removes friction, so the measured acceleration matches theory more closely).', 3, NULL, NULL),
('1466de79-06f8-5510-89cc-44c6190247ab', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 38, 38, 'A double-interrupt card has 3.0 cm segments. The block times are 0.060 s and 0.040 s, and the time between the two blocks is 0.25 s. Calculate the acceleration.', NULL, 2, 'numeric'::answer_type, '1', 'm s⁻²', false, NULL, false, NULL, 'u = 0.030 ÷ 0.060 = 0.50 m s⁻¹; v = 0.030 ÷ 0.040 = 0.75 m s⁻¹; a = (0.75 − 0.50) ÷ 0.25 = 1.0 m s⁻². Mark scheme (3 marks). C1: speeds. C1: a. A1: a = 1.0 m s⁻².', 3, NULL, NULL),
('83c8edf3-9c44-5e9a-8ce6-db71ee1dafe0', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 39, 39, 'A ramp 1.50 m long has one end raised by 0.12 m. Calculate the acceleration of a frictionless trolley on it. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.7848', 'm s⁻²', false, NULL, false, NULL, 'sin θ = 0.12 ÷ 1.50 = 0.080; a = 9.81 × 0.12 ÷ 1.50 = 0.785 m s⁻². Mark scheme (3 marks). C1: sin θ. C1: a = g sin θ. A1: a = 0.785 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgdf91e517-t fgdf91e517-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgdf91e517-t">Ramp</title><desc id="fgdf91e517-d">A ramp 1.50 m long with one end raised 0.12 m above the bench.</desc><line x1="63.6" y1="149.3" x2="290.1" y2="149.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,149.3 288.3,153.1 288.3,145.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="163.3" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">bench</text><line x1="296.4" y1="149.3" x2="296.4" y2="137" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,130.7 300.2,138.8 292.6,138.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="310.4" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">0.12 m</text><line x1="63.6" y1="149.3" x2="290.2" y2="131.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,130.7 288.6,135.1 288,127.5" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="181.1" y="154" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">1.50 m</text><circle cx="63.6" cy="149.3" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A ramp 1.50 m long with one end raised 0.12 m above the bench.'),
('6044c85d-1b87-550b-990c-8d91811a91aa', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 40, 40, 'A trolley released from rest reaches a light gate 0.50 m down a ramp at 0.80 m s⁻¹. Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '0.64', 'm s⁻²', false, NULL, false, NULL, 'a = 0.80² ÷ (2 × 0.50) = 0.64 m s⁻². Mark scheme (3 marks). C1: v² = 2as. C1: value. A1: a = 0.64 m s⁻².', 3, NULL, NULL),
('75ef74eb-581d-5092-84b1-c03a221e82be', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 41, 41, 'From rest, a trolley covers 0.90 m in 1.50 s. Find its acceleration assuming it is uniform.', NULL, 2, 'numeric'::answer_type, '0.8', 'm s⁻²', false, NULL, false, NULL, 'a = 2 × 0.90 ÷ 1.50² = 0.80 m s⁻². Mark scheme (3 marks). C1: s = ½at². C1: value. A1: a = 0.80 m s⁻².', 3, NULL, NULL),
('e019a646-43c8-5751-97aa-116cf3835bb4', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 42, 42, 'Why are the positions of the light gates marked on the ramp before repeat runs?', NULL, 2, 'multiple_choice'::answer_type, 'So that the distance between them stays the same for every run', NULL, false, NULL, false, NULL, 'A fixed separation is a control variable. Mark scheme (3 marks). C1: same s each run. C1: fair comparison. A1: C (So that the distance between them stays the same for every run).', 3, NULL, NULL),
('208c6d17-40d9-5362-b69f-e3cf819c02c6', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 43, 43, 'The gradient of a v–t graph from lab data is 0.48 m s⁻² with an uncertainty of ±0.03 m s⁻². Calculate the percentage uncertainty.', NULL, 2, 'numeric'::answer_type, '6.25', '%', false, NULL, false, NULL, '% = 0.03 ÷ 0.48 × 100 = 6.25 %. Mark scheme (3 marks). C1: Δa/a. C1: × 100. A1: % uncertainty = 6.25%.', 3, NULL, NULL),
('9c706428-65c2-592a-bbbf-b4e3bf094067', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'a-level', '2.7', '9702 coursebook 2.7 · Determining velocity and acceleration in the laboratory', 44, 44, 'A trolley is released from rest on a ramp. A light gate 0.64 m down the ramp records a 4.0 cm card taking 0.040 s. (a) Calculate the speed at the gate. (b) Calculate the acceleration. (c) Calculate the time from release to the gate.', NULL, 3, 'numeric'::answer_type, '1.28', 's', false, NULL, false, NULL, '(a) v = 0.040 ÷ 0.040 = 1.0 m s⁻¹. (b) a = 1.0² ÷ (2 × 0.64) = 0.781 m s⁻². (c) t = 1.0 ÷ 0.7813 = 1.28 s. Mark scheme (5 marks). C1: speed. M1: a = v²/2s. C1: value. C1: time. A1: t = 1.28 s.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg4a84a2b3-t fg4a84a2b3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4a84a2b3-t">Single gate on a ramp</title><desc id="fg4a84a2b3-d">A trolley carrying a 4.0 cm card passing a light gate 0.64 m from its release point.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line