INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('a8bf6ca3-790c-569e-9707-e6f85bee0e11', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 1, 1, 'Under what condition can the equations of motion (suvat) be used?', NULL, 1, 'multiple_choice'::answer_type, 'When the acceleration is constant (uniform) and the motion is in a straight line', NULL, false, NULL, false, NULL, 'They assume uniform acceleration. Mark scheme (1 mark). B1: C (When the acceleration is constant (uniform) and the motion is in a straight line).', 1, NULL, NULL),
('ba625f43-8365-5cc6-802e-2a4edc92f260', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 2, 2, 'A car starts from rest and accelerates at 2.5 m s⁻² for 8.0 s. Calculate its final velocity.', NULL, 1, 'numeric'::answer_type, '20', 'm s⁻¹', false, NULL, false, NULL, 'v = u + at = 0 + 2.5 × 8.0 = 20 m s⁻¹. Mark scheme (2 marks). C1: v = u + at. A1: v = 20 m s⁻¹.', 2, NULL, NULL),
('8d01f02c-02b6-5d46-883e-a37fac9f9df3', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 3, 3, 'A car starts from rest and accelerates at 2.5 m s⁻² for 8.0 s. Calculate how far it travels.', NULL, 1, 'numeric'::answer_type, '80', 'm', false, NULL, false, NULL, 's = ut + ½at² = 0 + 0.5 × 2.5 × 8.0² = 80 m. Mark scheme (2 marks). C1: s = ½at². A1: s = 80 m.', 2, NULL, NULL),
('bf751e85-5463-5bde-8cb0-51e431340e8b', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 4, 4, 'A cyclist accelerates from 3.0 m s⁻¹ to 7.0 m s⁻¹ over 20 m. Calculate her acceleration.', NULL, 1, 'numeric'::answer_type, '1', 'm s⁻²', false, NULL, false, NULL, 'a = (7.0² − 3.0²) ÷ (2 × 20) = 1.0 m s⁻². Mark scheme (2 marks). C1: v² = u² + 2as. A1: a = 1.0 m s⁻².', 2, NULL, NULL),
('5c37c784-ccaa-5f84-bdcf-25cc6ebc8287', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 5, 5, 'Which equation of motion does not contain the time t?', NULL, 1, 'multiple_choice'::answer_type, 'v² = u² + 2as', NULL, false, NULL, false, NULL, 'Use it when t is neither known nor wanted. Mark scheme (1 mark). B1: A (v² = u² + 2as).', 1, NULL, NULL),
('9aa9c87e-5f70-5e8a-9d6c-9c3cd1b58b0a', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 6, 6, 'A ball rolls from 2.0 m s⁻¹ to 6.0 m s⁻¹ in 4.0 s with uniform acceleration. Calculate the distance rolled.', NULL, 1, 'numeric'::answer_type, '16', 'm', false, NULL, false, NULL, 's = (u + v)t ÷ 2 = (2.0 + 6.0) × 4.0 ÷ 2 = 16 m. Mark scheme (2 marks). C1: s = (u + v)t/2. A1: s = 16 m.', 2, NULL, NULL),
('80f1fee9-80c6-5ce7-b77a-ba9aa1910cc7', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 7, 7, 'A train slows uniformly from 30 m s⁻¹ to rest at 0.50 m s⁻². Calculate the braking distance.', NULL, 1, 'numeric'::answer_type, '900', 'm', false, NULL, false, NULL, 's = (0 − 30²) ÷ (2 × −0.50) = 900 m. Mark scheme (2 marks). C1: v² = u² + 2as. A1: s = 900 m.', 2, NULL, NULL),
('0da82684-0cfe-593d-b8a1-e182facef92b', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 8, 8, 'In the suvat equations, what does s stand for?', NULL, 1, 'multiple_choice'::answer_type, 'Displacement', NULL, false, NULL, false, NULL, 's is the displacement from the starting point. Mark scheme (1 mark). B1: D (Displacement).', 1, NULL, NULL),
('e3905332-9f66-59d8-a164-43f86d88fecd', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 9, 9, 'A stone dropped from rest falls for 2.0 s. Calculate the distance fallen. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '19.62', 'm', false, NULL, false, NULL, 's = 0.5 × 9.81 × 2.0² = 19.6 m. Mark scheme (2 marks). C1: s = ½gt². A1: s = 19.6 m.', 2, NULL, NULL),
('7b51fbda-2b0d-5dcb-ac62-6af4b56161a7', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 10, 10, 'An object accelerates from 4.0 m s⁻¹ at 3.0 m s⁻² for 5.0 s. Calculate its final velocity.', NULL, 1, 'numeric'::answer_type, '19', 'm s⁻¹', false, NULL, false, NULL, 'v = 4.0 + 3.0 × 5.0 = 19 m s⁻¹. Mark scheme (2 marks). C1: v = u + at. A1: v = 19 m s⁻¹.', 2, NULL, NULL),
('e6402d32-dd6a-5c2f-b51d-69b7f6e4b8af', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 11, 11, 'A car brakes with uniform deceleration. Taking its direction of motion as positive, which quantity is negative?', NULL, 1, 'multiple_choice'::answer_type, 'The acceleration a', NULL, false, NULL, false, NULL, 'Deceleration is acceleration opposite to motion. Mark scheme (1 mark). B1: B (The acceleration a).', 1, NULL, NULL),
('1a3402c3-bd97-5723-a2be-17e6c3d6a1cb', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 12, 12, 'A runner accelerates from rest at 2.0 m s⁻² over 9.0 m. Calculate her final speed.', NULL, 1, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, 'v = √(0 + 2 × 2.0 × 9.0) = 6.0 m s⁻¹. Mark scheme (2 marks). C1: v² = 2as. A1: v = 6.0 m s⁻¹.', 2, NULL, NULL),
('e345d79a-9d8e-5b1b-8b3c-b8404d797d3c', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 13, 13, 'A car moving at 12 m s⁻¹ brakes at 4.0 m s⁻². How long does it take to stop?', NULL, 1, 'numeric'::answer_type, '3', 's', false, NULL, false, NULL, 't = (0 − 12) ÷ (−4.0) = 3.0 s. Mark scheme (1 mark). A1: t = 3.0 s.', 1, NULL, NULL),
('9e8a1e61-81b0-565a-8ff9-0fa4a89e45d6', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 14, 14, 'How many of the five suvat quantities must be known to find the others?', NULL, 1, 'multiple_choice'::answer_type, 'Three', NULL, false, NULL, false, NULL, 'Each equation links four of them. Mark scheme (1 mark). B1: C (Three).', 1, NULL, NULL),
('fb6cbadf-66d1-5dbe-981b-27b641d45be7', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 15, 15, 'A ball is thrown down a well at 5.0 m s⁻¹ and hits the water 2.0 s later. Calculate the depth. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '29.62', 'm', false, NULL, false, NULL, 's = 5.0 × 2.0 + 0.5 × 9.81 × 2.0² = 29.6 m. Mark scheme (2 marks). C1: s = ut + ½at². A1: s = 29.6 m.', 2, NULL, NULL),
('0d2a628b-a2ad-5d22-bc7a-92b52d268b4f', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 16, 16, 'A plane accelerates from rest at 4.0 m s⁻² until it reaches its take-off speed of 80 m s⁻¹. Calculate the runway length needed.', NULL, 1, 'numeric'::answer_type, '800', 'm', false, NULL, false, NULL, 's = 80² ÷ (2 × 4.0) = 800 m. Mark scheme (2 marks). C1: v² = 2as. A1: s = 800 m.', 2, NULL, NULL),
('a6fd6e52-fc80-5acf-b22f-e284fd6870ec', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 17, 17, 'A ball is thrown straight up. Taking up as positive, what value of a is used in the suvat equations?', NULL, 1, 'multiple_choice'::answer_type, '−9.81 m s⁻²', NULL, false, NULL, false, NULL, 'g acts downwards throughout. Mark scheme (1 mark). B1: A (−9.81 m s⁻²).', 1, NULL, NULL),
('34cc54ec-7efc-5d14-ae7d-98b0e42a8592', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 18, 18, 'A cyclist brakes uniformly from 8.0 m s⁻¹ to rest over 16 m. Calculate her deceleration.', NULL, 1, 'numeric'::answer_type, '2', 'm s⁻²', false, NULL, false, NULL, 'a = 8.0² ÷ (2 × 16) = 2.0 m s⁻². Mark scheme (2 marks). C1: v² = u² + 2as. A1: a = 2.0 m s⁻².', 2, NULL, NULL),
('99f03068-0c17-5df0-9e80-1de3911872db', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 19, 19, 'A ball rolls from rest down a slope with acceleration 0.50 m s⁻² for 6.0 s. Calculate the distance rolled.', NULL, 1, 'numeric'::answer_type, '9', 'm', false, NULL, false, NULL, 's = 0.5 × 0.50 × 6.0² = 9.0 m. Mark scheme (2 marks). C1: s = ½at². A1: s = 9.0 m.', 2, NULL, NULL),
('4719275e-8115-5038-b85c-cf4c6e5e2207', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 20, 20, 'A car speeds up uniformly from 10 m s⁻¹ to 25 m s⁻¹ in 5.0 s. Calculate its displacement in this time.', NULL, 1, 'numeric'::answer_type, '87.5', 'm', false, NULL, false, NULL, 's = (10 + 25) × 5.0 ÷ 2 = 87.5 m. Mark scheme (2 marks). C1: s = (u + v)t/2. A1: s = 87.5 m.', 2, NULL, NULL),
('2644bed4-0001-568e-943a-dfb714c0ea80', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 21, 21, 'A car moving at 15 m s⁻¹ accelerates at 1.5 m s⁻² for 6.0 s. Calculate the distance covered in this time.', NULL, 2, 'numeric'::answer_type, '117', 'm', false, NULL, false, NULL, 's = 15 × 6.0 + 0.5 × 1.5 × 6.0² = 117 m. Mark scheme (3 marks). C1: s = ut + ½at². C1: value. A1: s = 117 m.', 3, NULL, NULL),
('18d50b79-5958-5337-bb89-ce5d9cbb4e41', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 22, 22, 'A ball is thrown vertically upwards at 18 m s⁻¹. Calculate the maximum height reached. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '16.51', 'm', false, NULL, false, NULL, 'h = 18² ÷ (2 × 9.81) = 16.5 m. Mark scheme (3 marks). C1: v = 0 at top. C1: v² = u² + 2as. A1: h = 16.5 m.', 3, NULL, NULL),
('2673b654-4c5a-51a7-8251-21628d3d4c82', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 23, 23, 'A car decelerates uniformly from 25 m s⁻¹ to 10 m s⁻¹ over 70 m. Calculate its deceleration.', NULL, 2, 'numeric'::answer_type, '3.75', 'm s⁻²', false, NULL, false, NULL, 'a = (10² − 25²) ÷ (2 × 70) = −3.75 m s⁻², so the deceleration is (25² − 10²) ÷ (2 × 70) = 3.75 m s⁻². Mark scheme (3 marks). C1: v² = u² + 2as. C1: magnitude. A1: a = 3.75 m s⁻².', 3, NULL, NULL),
('5d204e97-42c3-532d-bb22-2cfec8a5a3ed', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 24, 24, 'A stone thrown upwards at 12 m s⁻¹ from a cliff top lands on the beach 3.0 s later. Taking up as positive, calculate its displacement. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '-8.145', 'm', false, NULL, true, NULL, 's = 12 × 3.0 − 0.5 × 9.81 × 3.0² = −8.15 m (8.15 m below the start). Mark scheme (3 marks). C1: a = −9.81. C1: value with sign. A1: s = −8.15 m.', 3, NULL, NULL),
('6da7c007-55a6-5ddd-ab4f-406fdb2a180f', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 25, 25, 'A sprinter accelerates uniformly from rest to 10 m s⁻¹ over the first 20 m. Calculate the time taken.', NULL, 2, 'numeric'::answer_type, '4', 's', false, NULL, false, NULL, 's = (u + v)t ÷ 2, so t = 2 × 20 ÷ (0 + 10) = 4.0 s. Mark scheme (3 marks). C1: s = (u + v)t/2. C1: rearranged. A1: t = 4.0 s.', 3, NULL, NULL),
('eccfe332-b234-5e63-ab5e-7e96ad3b78f8', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 26, 26, 'A car travels 50 m while slowing uniformly from 20 m s⁻¹ to 10 m s⁻¹. Which pair of equations gives a and t most directly?', NULL, 2, 'multiple_choice'::answer_type, 'v² = u² + 2as for a, then s = (u + v)t/2 for t', NULL, false, NULL, false, NULL, 'Choose equations containing the known quantities. Mark scheme (3 marks). C1: a from v². C1: t from average. A1: D (v² = u² + 2as for a, then s = (u + v)t/2 for t).', 3, NULL, NULL),
('903dea31-49c3-5e0f-8218-b1738c2410f6', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 27, 27, 'A car slows uniformly from 20 m s⁻¹ to 10 m s⁻¹ over 50 m. Calculate the time taken.', NULL, 2, 'numeric'::answer_type, '3.333', 's', false, NULL, false, NULL, 't = 2 × 50 ÷ (20 + 10) = 3.33 s. Mark scheme (3 marks). C1: s = (u + v)t/2. C1: value. A1: t = 3.33 s.', 3, NULL, NULL),
('209bbb9a-4756-57d0-957d-d69effe384bf', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 28, 28, 'An electron accelerates uniformly from rest at 4.0 × 10¹⁴ m s⁻² over 2.0 cm. Calculate its final speed, in units of 10⁶ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '4', '10⁶ m s⁻¹', false, NULL, false, NULL, 'v = √(2 × 4.0 × 10¹⁴ × 0.020) = 4.00 × 10⁶ m s⁻¹. Mark scheme (3 marks). C1: v² = 2as. C1: cm to m. A1: v = 4.00 × 10⁶ m s⁻¹.', 3, NULL, NULL),
('72f04691-c0e1-5b61-88fb-2e83fb3812f9', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 29, 29, 'A ball is dropped from a 45 m tower. Calculate the time it takes to reach the ground. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '3.029', 's', false, NULL, false, NULL, 't = √(2 × 45 ÷ 9.81) = 3.03 s. Mark scheme (3 marks). C1: s = ½gt². C1: value. A1: t = 3.03 s.', 3, NULL, NULL),
('0e3c5cee-6f64-5204-b6a9-807fb3094dd9', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 30, 30, 'A ball is dropped from a 45 m tower. Calculate its speed on reaching the ground. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '29.71', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2 × 9.81 × 45) = 29.7 m s⁻¹. Mark scheme (3 marks). C1: v² = 2gs. C1: value. A1: v = 29.7 m s⁻¹.', 3, NULL, NULL),
('00897f5e-3e79-533d-9938-e85c8cea7eb3', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 31, 31, 'A car travelling at 30 m s⁻¹ brakes uniformly and stops in 75 m. Calculate the time taken to stop.', NULL, 2, 'numeric'::answer_type, '5', 's', false, NULL, false, NULL, 'a = −30² ÷ (2 × 75) = −6.0 m s⁻²; t = 30 ÷ 6.0 = 5.0 s. Mark scheme (4 marks). C1: a. M1: t = Δv/a or average speed. C1: value. A1: t = 5.0 s.', 4, NULL, NULL),
('34527546-4f5a-53e9-b004-6dc77211845b', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 32, 32, 'A lift accelerates upwards from rest at 0.80 m s⁻² for 3.0 s. Calculate the height it rises in that time.', NULL, 2, 'numeric'::answer_type, '3.6', 'm', false, NULL, false, NULL, 's = 0.5 × 0.80 × 3.0² = 3.6 m. Mark scheme (3 marks). C1: s = ½at². C1: value. A1: s = 3.6 m.', 3, NULL, NULL),
('0a04d792-49a5-5880-8b4f-dddd85b0ebcf', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 33, 33, 'A ball is thrown upwards at 10 m s⁻¹ and caught at the same height. Why does s = 0 give two solutions for t?', NULL, 2, 'multiple_choice'::answer_type, 'One is t = 0 (at release) and the other is when it returns', NULL, false, NULL, false, NULL, 'ut + ½at² = 0 has roots t = 0 and t = −2u/a. Mark scheme (3 marks). C1: t = 0. C1: return time. A1: B (One is t = 0 (at release) and the other is when it returns).', 3, NULL, NULL),
('14aec8ee-48cc-5bff-99fa-3ab6cb3ea448', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 34, 34, 'A ball is thrown upwards at 10 m s⁻¹ and caught at the same height. Calculate the time of flight. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '2.039', 's', false, NULL, false, NULL, 't = 2 × 10 ÷ 9.81 = 2.04 s. Mark scheme (3 marks). C1: s = 0. C1: t = 2u/g. A1: t = 2.04 s.', 3, NULL, NULL),
('9c7b185c-1389-5065-875b-674ecf607a30', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 35, 35, 'A train accelerates uniformly from 8.0 m s⁻¹ to 20 m s⁻¹ while travelling 280 m. Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '0.6', 'm s⁻²', false, NULL, false, NULL, 'a = (20² − 8.0²) ÷ (2 × 280) = 0.60 m s⁻². Mark scheme (3 marks). C1: v² = u² + 2as. C1: value. A1: a = 0.60 m s⁻².', 3, NULL, NULL),
('fd0a9102-7d57-5d57-ac9a-8ff75fac580c', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 36, 36, 'A hockey puck slides 24 m and stops, decelerating uniformly at 0.75 m s⁻². Calculate its initial speed.', NULL, 2, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, 'u = √(2 × 0.75 × 24) = 6.0 m s⁻¹. Mark scheme (3 marks). C1: 0 = u² − 2as. C1: value. A1: u = 6.0 m s⁻¹.', 3, NULL, NULL),
('b1d078a7-497f-51f2-bda7-ba509d31a694', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 37, 37, 'A rocket accelerates upwards from rest at 15 m s⁻² for 10 s. Calculate its height at the end of the burn.', NULL, 2, 'numeric'::answer_type, '750', 'm', false, NULL, false, NULL, 's = 0.5 × 15 × 10² = 750 m. Mark scheme (3 marks). C1: s = ½at². C1: value. A1: h = 750 m.', 3, NULL, NULL),
('f68cb806-a5c4-5a62-a448-6462b0ff8f2c', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 38, 38, 'A bullet passes through a 0.12 m thick plank, slowing from 400 m s⁻¹ to 250 m s⁻¹. Calculate its deceleration, in units of 10⁵ m s⁻².', NULL, 2, 'numeric'::answer_type, '4.062', '10⁵ m s⁻²', false, NULL, false, NULL, 'a = (400² − 250²) ÷ (2 × 0.12) = 4.06 × 10⁵ m s⁻² (as a deceleration). Mark scheme (3 marks). C1: v² = u² + 2as. C1: value. A1: a = 4.06 × 10⁵ m s⁻².', 3, NULL, NULL),
('35837935-e714-564d-89ba-a42e286e4bc9', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 39, 39, 'A stone is thrown vertically upwards at 20 m s⁻¹. Calculate the time it takes to reach its highest point. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '2.039', 's', false, NULL, false, NULL, 't = 20 ÷ 9.81 = 2.04 s. Mark scheme (3 marks). C1: v = 0 at top. C1: t = u/g. A1: t = 2.04 s.', 3, NULL, NULL),
('0f5ffc4e-ba88-5d7a-ab5f-108a48f94e0b', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 40, 40, 'A car accelerates at 1.2 m s⁻² from 5.0 m s⁻¹. How far does it travel before reaching 17 m s⁻¹?', NULL, 2, 'numeric'::answer_type, '110', 'm', false, NULL, false, NULL, 's = (17² − 5.0²) ÷ (2 × 1.2) = 110 m. Mark scheme (3 marks). C1: v² = u² + 2as. C1: value. A1: s = 110 m.', 3, NULL, NULL),
('b289405f-ddef-594a-a49f-007a204e4903', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 41, 41, 'A train passes a signal at 25 m s⁻¹ and stops 500 m further on, decelerating uniformly. Calculate the deceleration.', NULL, 2, 'numeric'::answer_type, '0.625', 'm s⁻²', false, NULL, false, NULL, 'a = 25² ÷ (2 × 500) = 0.625 m s⁻². Mark scheme (3 marks). C1: v² = u² + 2as. C1: value. A1: a = 0.625 m s⁻².', 3, NULL, NULL),
('0b996f18-ace8-580f-8532-a36cd6171e05', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 42, 42, 'An object dropped from rest falls 5.0 m. Calculate its speed. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '9.905', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2 × 9.81 × 5.0) = 9.90 m s⁻¹. Mark scheme (3 marks). C1: v² = 2gs. C1: value. A1: v = 9.90 m s⁻¹.', 3, NULL, NULL),
('80a35b94-3af8-5330-91aa-6e3d8b39c6cc', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 43, 43, 'A sprinter accelerates uniformly from rest at 3.0 m s⁻². How long does she take to cover 24 m?', NULL, 2, 'numeric'::answer_type, '4', 's', false, NULL, false, NULL, 't = √(2 × 24 ÷ 3.0) = 4.0 s. Mark scheme (3 marks). C1: s = ½at². C1: rearranged. A1: t = 4.0 s.', 3, NULL, NULL),
('456bd85c-8ac2-5f26-a9e9-6d798ab1129c', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 44, 44, 'A car passes a point at 12 m s⁻¹ and accelerates uniformly at 2.0 m s⁻². (a) Calculate its speed after travelling a further 64 m. (b) Calculate the time taken.', NULL, 3, 'numeric'::answer_type, '4', 's', false, NULL, false, NULL, '(a) v = √(12² + 2 × 2.0 × 64) = 20 m s⁻¹. (b) t = (20 − 12) ÷ 2.0 = 4.0 s. Mark scheme (5 marks). M1: v² = u² + 2as. C1: v = 20. M1: v = u + at. C1: value. A1: t = 4.0 s.', 5, NULL, NULL),
('c4f86d93-e1b7-5556-93f2-cd3f97940473', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'a-level', '2.8', '9702 coursebook 2.8 · The equations of motion', 45, 45, 'A ball is thrown upwards at 15 m s⁻¹ from the top of a 20 m cliff and falls to the beach below. Taking up as positive: (a) write the equation for its displacement −20 m; (b) solve for the time of flight; (c) calculate its speed at impact. Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '24.85', 'm s⁻¹', false, NULL, false, NULL, '(a) The displacement 15t − 4.905t² must equal −20 m. (b) t = (15 + √(15² + 4 × 4.905 × 20)) ÷ (2 × 4.905) = 4.06 s. (c) v = √(15² + 2 × 9.81 × 20) = 24.8 m s⁻¹. Mark scheme (6 marks). B1: equation with signs. M1: quadratic formula. C1: time. M1: v² = u² + 2as. C1: value. A1: v = 24.8 m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg9a2f4032-t fg9a2f4032-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9a2f4032-t">Ball thrown from a cliff</title><desc id="fg9a2f4032-d">Height above the beach against time for a ball thrown up at 15 m s⁻¹ from a 20 m cliff: it rises, turns and falls past the cliff top to the beach.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="107.8" y1="34" x2="107.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="186.1" y1="34" x2="186.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="264.5" y1="34" x2="264.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="342.8" y1="34" x2="342.8" y2="242" style="stroke:var(-