" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="264.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="342.8" y1="242" x2="342.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="342.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="182.6" x2="29.4" y2="182.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="182.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="123.1" x2="29.4" y2="123.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="123.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><line x1="25.4" y1="63.7" x2="29.4" y2="63.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="63.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">30</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">height above beach / m</text><line x1="29.4" y1="123.1" x2="382" y2="123.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray: