INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('4f59b078-4975-5ee3-bb69-10989d7fccd1', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 1, 1, 'Which equation of motion comes directly from the definition of acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'v = u + at', NULL, false, NULL, false, NULL, 'a = (v − u)/t rearranges to v = u + at. Mark scheme (1 mark). B1: C (v = u + at).', 1, NULL, NULL),
('13b806fd-98f5-53f3-b2c7-c3a131c9307e', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 2, 2, 'Which feature of a v–t graph is used to derive s = (u + v)t/2?', NULL, 1, 'multiple_choice'::answer_type, 'The area under the graph (a trapezium)', NULL, false, NULL, false, NULL, 'Area = average of parallel sides × width. Mark scheme (1 mark). B1: A (The area under the graph (a trapezium)).', 1, NULL, NULL),
('8df20c2e-afd3-51eb-be79-0071eff24166', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 3, 3, 'For uniform acceleration, what is the average velocity between u and v?', NULL, 1, 'multiple_choice'::answer_type, '(u + v)/2', NULL, false, NULL, false, NULL, 'The v–t graph is a straight line. Mark scheme (1 mark). B1: D ((u + v)/2).', 1, NULL, NULL),
('2db29670-2410-5268-a956-642b4255efc6', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 4, 4, 'For uniform acceleration from 6.0 m s⁻¹ to 14 m s⁻¹, calculate the average velocity.', NULL, 1, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, 'v_avg = (6.0 + 14) ÷ 2 = 10 m s⁻¹. Mark scheme (2 marks). C1: (u + v)/2. A1: v = 10 m s⁻¹.', 2, NULL, NULL),
('7dc62140-d8c1-5e17-ab65-0bcb2c3992ac', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 5, 5, 'The area under a v–t graph for uniform acceleration can be split into a rectangle and a triangle. What does the rectangle represent?', NULL, 1, 'multiple_choice'::answer_type, 'ut, the displacement at the initial speed', NULL, false, NULL, false, NULL, 'Rectangle height u, width t. Mark scheme (1 mark). B1: B (ut, the displacement at the initial speed).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgf378487c-t fgf378487c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf378487c-t">Splitting the area</title><desc id="fgf378487c-d">The trapezium under a straight v–t line from u to v, split by a dashed line at v = u into a rectangle (ut) and a triangle (½at²).</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="130.2" y1="34" x2="130.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230.9" y1="34" x2="230.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="331.6" y1="34" x2="331.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="172.7" x2="382" y2="172.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="103.3" x2="382" y2="103.3"