e-linejoin:round"/><text x="22.4" y="125" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">9</text><line x1="25.4" y1="86" x2="29.4" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">12</text><line x1="25.4" y1="47" x2="29.4" y2="47" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="47" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">15</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">v / m s⁻¹</text><polygon points="29.4,242 382,47 382,242 29.4,242" style="stroke:none;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polyline points="29.4,242 382,47" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="100,242 100,203" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="170.5,242 170.5,164" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="241,242 241,125" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="311.5,242 311.5,86" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A straight v–t line from rest with gradient 3.0 m s⁻² for 5.0 s; the strips for each second have areas in the ratio 1 : 3 : 5 : 7 : 9.'),
('368536c5-35be-5703-a960-41c232825cd3', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 46, 46, 'A train passes two posts 100 m apart, taking 8.0 s for the first 100 m and 6.0 s for the next 100 m, accelerating uniformly. (a) Calculate its average speeds in each interval. (b) Using these as speeds at mid-times, calculate the acceleration.', NULL, 3, 'numeric'::answer_type, '0.5952', 'm s⁻²', false, NULL, false, NULL, '(a) 100 ÷ 8.0 = 12.5 m s⁻¹; 100 ÷ 6.0 = 16.67 m s⁻¹. (b) Mid-times are 4.0 s and 11 s, 7.0 s apart: a = (16.67 − 12.5) ÷ 7.0 = 0.595 m s⁻². Mark scheme (5 marks). C1: average speeds. M1: speeds at mid-times. C1: Δt = 7.0 s. C1: value. A1: a = 0.595 m s⁻².', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fgeddf91cd-t fgeddf91cd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgeddf91cd-t">Three posts</title><desc id="fgeddf91cd-d">Three posts 100 m apart along a track; the train takes 8.0 s for the first gap and 6.0 s for the second.</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><circle cx="46" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">post 1</text><circle cx="230" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="230" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">post 2</text><circle cx="414" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="414" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">post 3</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="225.1" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,116 223.7,119 223.7,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="138" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100 m, 8.0 s</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="230" y1="74" x2="230" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><polygon points="230,146 236.3,143 236.3,149" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="234.9" y1="146" x2="409.1" y2="146" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="414,146 407.7,149 407.7,143" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="322" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100 m, 6.0 s</text><line x1="230" y1="74" x2="230" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="414" y1="74" x2="414" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'Three posts 100 m apart along a track; the train takes 8.0 s for the first gap and 6.0 s for the second.'),
('88d4c01f-c459-5b18-8c0d-01a5a70a44a4', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 47, 47, 'Using s = ut + ½at², derive an expression for the time for a ball thrown upwards at u to return to its starting height, then (a) evaluate it for u = 14.7 m s⁻¹ and (b) find the maximum height. Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '11.01', 'm', false, NULL, false, NULL, '0 = ut − ½gt² gives t = 2u/g. (a) t = 2 × 14.7 ÷ 9.81 = 3.00 s. (b) h = 14.7² ÷ (2 × 9.81) = 11.0 m. Mark scheme (6 marks). M1: s = 0. B1: t = 2u/g. C1: value. M1: v² = u² − 2gh. C1: value. A1: h = 11.0 m.', 6, NULL, NULL),
('97606f74-ae63-5092-a3c6-9742653fe697', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 48, 48, 'A car moving at u accelerates uniformly for 5.0 s, covering 75 m and reaching 20 m s⁻¹. (a) Use s = (u + v)t/2 to find u. (b) Find the acceleration.', NULL, 3, 'numeric'::answer_type, '2', 'm s⁻²', false, NULL, false, NULL, '(a) 75 = (u + 20) × 5.0 ÷ 2, so u = 2 × 75 ÷ 5.0 − 20 = 10 m s⁻¹. (b) a = (20 − 10) ÷ 5.0 = 2.0 m s⁻². Mark scheme (5 marks). M1: rearrange. C1: u. M1: a = Δv/t. C1: value. A1: a = 2.0 m s⁻².', 5, NULL, NULL),
('7e332715-baf9-55d5-a521-48ad83da45b0', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 49, 49, 'For constant acceleration, show that the speed at the mid-point in time is (u + v)/2 but the speed at the mid-point in distance is √((u² + v²)/2). Calculate the second for u = 2.0 m s⁻¹ and v = 14 m s⁻¹.', NULL, 3, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, 'Mid-distance: v_m² = u² + 2a(s/2) = u² + (v² − u²)/2 = (u² + v²)/2. v_m = √((2.0² + 14²) ÷ 2) = 10.0 m s⁻¹. Mark scheme (5 marks). M1: v² = u² + 2a(s/2). B1: algebra. C1: substitution. C1: value. A1: v_m = 10 m s⁻¹.', 5, NULL, NULL),
('f4736ba3-6930-5cbf-b2c3-cc4359506f12', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 50, 50, 'A cyclist passes point P at 4.0 m s⁻¹ and point Q, 60 m further on, at 8.0 m s⁻¹, accelerating uniformly. (a) Calculate the acceleration. (b) Calculate the time from P to Q. (c) Calculate her speed half way in time between P and Q.', NULL, 3, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, '(a) a = (8.0² − 4.0²) ÷ (2 × 60) = 0.40 m s⁻². (b) t = 2 × 60 ÷ (4.0 + 8.0) = 10 s. (c) v = 4.0 + 0.40 × 5.0 = 6.0 m s⁻¹. Mark scheme (6 marks). C1: a. C1: t. M1: mid-time. C1: substitution. C1: value. A1: v = 6.0 m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg93542b9e-t fg93542b9e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg93542b9e-t">P to Q</title><desc id="fg93542b9e-d">A straight v–t line from 4.0 m s⁻¹ at P to 8.0 m s⁻¹ at Q, 10 s later, with the 60 m area shaded.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="34" x2="100" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170.5" y1="34" x2="170.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241" y1="34" x2="241" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="311.5" y1="34" x2="311.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="200.4" x2="382" y2="200.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="158.8" x2="382" y2="158.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="117.2" x2="382" y2="117.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="75.6" x2="382" y2="75.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="100" y1="242" x2="100" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="100" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="170.5" y1="242" x2="170.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="170.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="241" y1="242" x2="241" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="241" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="311.5" y1="242" x2="311.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="311.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="200.4" x2="29.4" y2="200.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="200.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="25.4" y1="158.8" x2="29.4" y2="158.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="158.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="25.4" y1="117.2" x2="29.4" y2="117.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="117.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="25.4" y1="75.6" x2="29.4" y2="75.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="75.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">v / m s⁻¹</text><polygon points="29.4,158.8 382,75.6 382,242 29.4,242" style="stroke:none;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polyline points="29.4,158.8 382,75.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A straight v–t line from 4.0 m s⁻¹ at P to 8.0 m s⁻¹ at Q, 10 s later, with the 60 m area shaded.'),
('58ebc3e2-651b-55d6-bf9d-6e870e9c4459', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 51, 51, 'Show that for a body decelerating uniformly to rest, the stopping distance is proportional to u². If a car stops in 20 m from 15 m s⁻¹, calculate its stopping distance from 30 m s⁻¹ with the same deceleration.', NULL, 3, 'numeric'::answer_type, '80', 'm', false, NULL, false, NULL, 's = u²/(2a), so s ∝ u². Doubling u multiplies s by 2² = 4: s = 20 × 4 = 80 m. Mark scheme (5 marks). M1: s = u²/2a. B1: s ∝ u². M1: factor 4. C1: value. A1: s = 80 m.', 5, NULL, NULL),
('ea52da92-807a-5721-be99-1d54c75844d9', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 52, 52, 'For a body decelerating uniformly from u to rest at a: (a) show that the stopping time is u/a; (b) show that the stopping distance is u²/2a; (c) calculate the stopping distance for u = 18 m s⁻¹ and a = 4.5 m s⁻².', NULL, 3, 'numeric'::answer_type, '36', 'm', false, NULL, false, NULL, '(a) 0 = u − at gives t = u/a. (b) s = ut − ½at² = u²/a − u²/2a = u²/2a. (c) s = 18² ÷ (2 × 4.5) = 36 m. Mark scheme (5 marks). B1: time. B1: distance. M1: substitution. C1: value. A1: s = 36 m.', 5, NULL, NULL),
('006f19a2-522b-597e-acda-d8bf9211d49c', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'a-level', '2.9', '9702 coursebook 2.9 · Deriving the equations of motion', 53, 53, 'For an object falling from rest, show using s = ½gt² that the distances fallen in successive intervals of length T differ by gT². Calculate gT² for T = 0.10 s. Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.0981', 'm', false, NULL, false, NULL, 'Interval n covers ½g(nT)² − ½g((n − 1)T)² = ½gT²(2n − 1); successive intervals differ by gT². gT² = 9.81 × 0.10² = 0.0981 m. Mark scheme (5 marks). M1: difference of squares. B1: increments of gT². C1: substitution. C1: value. A1: gT² = 0.0981 m.', 5, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('11ab5532-2875-59d2-9767-c5621ce7d3a2', '4f59b078-4975-5ee3-bb69-10989d7fccd1', 's = ut + ½at²', 'A', false, 0),
