('87b1a791-eaa6-5cda-b3da-4226e65203f7', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'a-level', '2.10', '9702 coursebook 2.10 · Uniform and non-uniform acceleration', 1, 1, 'What is meant by uniform acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'Acceleration that stays constant in size and direction', NULL, false, NULL, false, NULL, 'Its v–t graph is a straight line. Mark scheme (1 mark). B1: C (Acceleration that stays constant in size and direction).', 1, NULL, NULL),
('f5906ff2-5462-565c-b08b-d89a5a7f7f92', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'a-level', '2.10', '9702 coursebook 2.10 · Uniform and non-uniform acceleration', 2, 2, 'Which v–t graph shows non-uniform acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'A curved line', NULL, false, NULL, false, NULL, 'A changing gradient means a changing acceleration. Mark scheme (1 mark). B1: A (A curved line).', 1, NULL, NULL),
('9112e23c-c7db-501f-a49b-fcaf6bf8db72', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'a-level', '2.10', '9702 coursebook 2.10 · Uniform and non-uniform acceleration', 3, 3, 'Can the suvat equations be used for non-uniform acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'No, they apply only when the acceleration is constant', NULL, false, NULL, false, NULL, 'Non-uniform motion needs graphs or other methods. Mark scheme (1 mark). B1: D (No, they apply only when the acceleration is constant).', 1, NULL, NULL),
