('fc57a7a3-e31e-5247-a5dc-1cafe06ecc54', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'a-level', '2.10', '9702 coursebook 2.10 · Uniform and non-uniform acceleration', 32, 32, 'A train''s acceleration is 0.50 m s⁻² for 20 s and then 0.20 m s⁻² for 30 s, starting from rest. Calculate its final speed.', NULL, 2, 'numeric'::answer_type, '16', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.50 × 20 + 0.20 × 30 = 16 m s⁻¹. Mark scheme (3 marks). C1: each stage. C1: sum. A1: v = 16 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg8569fff7-t fg8569fff7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8569fff7-t">Two-stage acceleration</title><desc id="fg8569fff7-d">An a–t graph at 0.50 m s⁻² for 20 s then 0.20 m s⁻² for 30 s, with the area shaded.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="102.8" y1="34" x2="102.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172.6" y1="34" x2="172.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="242.4" y1="34" x2="242.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.2" y1="34" x2="312.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linej