('81667da1-9fdc-504e-84ef-1f57b9202e0f', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'a-level', '2.10', '9702 coursebook 2.10 · Uniform and non-uniform acceleration', 42, 42, 'Is the acceleration of a bouncing ball uniform throughout its motion?', NULL, 2, 'multiple_choice'::answer_type, 'No: it is g downwards in the air but large and upwards while in contact with the floor', NULL, false, NULL, false, NULL, 'The contact force acts briefly. Mark scheme (3 marks). C1: in flight g. C1: contact large upward. A1: B (No: it is g downwards in the air but large and upwards while in contact with the floor).', 3, NULL, NULL),
('54ade9a8-e734-5b34-8ba2-6ee742d4b549', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'a-level', '2.10', '9702 coursebook 2.10 · Uniform and non-uniform acceleration', 43, 43, 'A ball falling through air has speeds of 12.0 m s⁻¹ at 1.5 s and 15.2 m s⁻¹ at 2.0 s. Calculate its average acceleration over this interval.', NULL, 2, 'numeric'::answer_type, '6.4', 'm s⁻²', false, NULL, false, NULL, 'a = (15.2 − 12.0) ÷ 0.50 = 6.4 m s⁻². Mark scheme (3 marks). C1: Δv. C1: ÷ Δt. A1: a = 6.4 m s⁻².', 3, NULL, NULL),
('0ff5e6f7-80fc-50a1-9f81-ec00ae201080', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'a-level', '2.10', '9702 coursebook 2.10 · Uniform and non-uniform acceleration', 44, 44, 'A cyclist''s speed is 2.0, 3.5, 4.5 and 5.0 m s⁻¹ at t = 0, 2.0, 4.0 and 6.0 s. Estimate the distance travelled using trapezia.', NULL, 2, 'numeric'::answer_type, '23', 'm', false, NULL, false, NULL, 's = (2.0 + 3.5) ÷ 2 × 2.0 + (3.5 + 4.5) ÷ 2 × 2.0 + (4.5 + 5.0) ÷ 2 × 2.0 = 23 m. Mark scheme (3 marks). C1: trapezia. C1: sum. A1: s = 23 m.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgbae55c14-t fgbae55c14-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbae55c14-t">Cyclist</title><desc id="fgbae55c14-d">Speed readings 2.0, 3.5, 4.5 and 5.0 m s⁻¹ at 0, 2.0, 4.0 and 6.0 s joined by straight lines, with the trapezia shaded.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83.7" y1="34" x2="83.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="143.3" y1="34" x2="143.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="203" y1="34" x2="203" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="262.7" y1="34" x2="262.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="322.3" y1="34" x2="322.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);str